// ---------------------------------------------------------------------------
// The sitcom, as the app sees it. lib/sitcom.ts is generated by the sitcom
// pipeline; this wrapper only shows episodes that belong to a History topic
// and reads the show's name if the manifest exports one (SITCOM_SHOW).
// ---------------------------------------------------------------------------
import * as sitcom from "./sitcom";
import type { SitcomEpisode } from "./sitcom";
import { TOPIC_META } from "./topics/meta";

export type { SitcomEpisode };

const KNOWN_TOPICS = new Set(TOPIC_META.map((t) => t.id));

function exported(name: string): unknown {
  // Computed access, so a manifest without this export still builds.
  return (sitcom as unknown as Record<string, unknown>)[name];
}

const named = exported("SITCOM_SHOW");

/** The sitcom's title, e.g. "Who Rules the Remote?". */
export const SHOW_NAME: string = typeof named === "string" && named.trim() ? named.trim() : "Who Rules the Remote?";

/** Episodes for History topics, in episode order. */
export const EPISODES: SitcomEpisode[] = sitcom.SITCOM_EPISODES.filter((e) => KNOWN_TOPICS.has(e.topicId)).sort((a, b) => a.num - b.num);

/** The episode for one topic, if it has been made. */
export function episodeFor(topicId: string): SitcomEpisode | undefined {
  return KNOWN_TOPICS.has(topicId) ? sitcom.sitcomEpisodeFor(topicId) : undefined;
}
